draw:
var f1 = p.f1, f2 = p.f2;
var pad = 40;
var Tw = 2.0;
var X = function (s) { return pad + s / Tw * (W - pad - 12); };

ctx.lineWidth = 1;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

var y1 = H * 0.16, y2 = H * 0.36, ys = H * 0.72;
var a  = H * 0.072, as = H * 0.19;

// baselines
ctx.strokeStyle = C.faint;
var rows = [y1, y2, ys];
for (var r = 0; r < rows.length; r++) {
  ctx.beginPath(); ctx.moveTo(pad, rows[r]); ctx.lineTo(W - 10, rows[r]); ctx.stroke();
}

var N = 700, i, s;

// the two pure tones
ctx.strokeStyle = C.rule;
ctx.beginPath();
for (i = 0; i <= N; i++) { s = Tw * i / N; ctx.lineTo(X(s), y1 - a * Math.cos(2 * Math.PI * f1 * s)); }
ctx.stroke();
ctx.beginPath();
for (i = 0; i <= N; i++) { s = Tw * i / N; ctx.lineTo(X(s), y2 - a * Math.cos(2 * Math.PI * f2 * s)); }
ctx.stroke();

// envelope
ctx.strokeStyle = C.figure;
ctx.setLineDash([4, 4]);
ctx.beginPath();
for (i = 0; i <= N; i++) { s = Tw * i / N; ctx.lineTo(X(s), ys - as * Math.cos(Math.PI * (f1 - f2) * s)); }
ctx.stroke();
ctx.beginPath();
for (i = 0; i <= N; i++) { s = Tw * i / N; ctx.lineTo(X(s), ys + as * Math.cos(Math.PI * (f1 - f2) * s)); }
ctx.stroke();
ctx.setLineDash([]);

// the sum
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
ctx.beginPath();
for (i = 0; i <= N; i++) {
  s = Tw * i / N;
  var yv = 0.5 * as * (Math.cos(2 * Math.PI * f1 * s) + Math.cos(2 * Math.PI * f2 * s));
  ctx.lineTo(X(s), ys - yv);
}
ctx.stroke();
ctx.lineWidth = 1;

// moving cursor
var now = t % Tw;
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(X(now), H * 0.06); ctx.lineTo(X(now), H * 0.96); ctx.stroke();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "right";
ctx.fillText("f1", pad - 6, y1);
ctx.fillText("f2", pad - 6, y2);
ctx.fillText("sum", pad - 6, ys);
ctx.textAlign = "left";
ctx.fillStyle = C.figure;
ctx.fillText("envelope", pad + 6, ys - as - 10);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("time (s)", W / 2, H - 8);
ctx.textAlign = "left";
ctx.fillText("0", pad - 3, H - 8);
ctx.textAlign = "right";
ctx.fillText(Tw.toFixed(1), W - 12, H - 8);

var fb = Math.abs(f1 - f2);
var note = "beat frequency " + fb.toFixed(2) + " Hz";
if (fb > 0) { note += ", one loud moment every " + (1 / fb).toFixed(3) + " s"; }
else { note += " (identical tones, no beating)"; }
note += "  -  envelope repeats half as often as the loudness does";
out.note = note;

var d = p.sep, f = p.freq, yl = p.pos;
var L = 4.0;
var lam = 343 / f;
var r1 = Math.sqrt(L * L + (yl + d / 2) * (yl + d / 2));
var r2 = Math.sqrt(L * L + (yl - d / 2) * (yl - d / 2));
var dr = r1 - r2;
var n = dr / lam;

var pad = 46;
var halfY = Math.max(d / 2, Math.abs(yl)) + 0.6;
var sc = Math.min((W - pad - 26) / (L + 0.5), (H - 46) / (2 * halfY));
var cx = pad, cy = H / 2;
var PX = function (x) { return cx + x * sc; };
var PY = function (y) { return cy - y * sc; };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

// the wall
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(PX(0), 8); ctx.lineTo(PX(0), H - 8); ctx.stroke();

// the walking line
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(PX(L), 12); ctx.lineTo(PX(L), H - 12); ctx.stroke();
ctx.setLineDash([]);

var sy1 = d / 2, sy2 = -d / 2;

// paths
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(PX(0), PY(sy1)); ctx.lineTo(PX(L), PY(yl)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(PX(0), PY(sy2)); ctx.lineTo(PX(L), PY(yl)); ctx.stroke();

// speakers
ctx.fillStyle = C.ink;
ctx.fillRect(PX(0) - 5, PY(sy1) - 8, 10, 16);
ctx.fillRect(PX(0) - 5, PY(sy2) - 8, 10, 16);

// listener, pulsing gently so the eye finds her
var pulse = 5 + 1.2 * (1 + Math.sin(2 * Math.PI * t / 1.5)) / 2;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(PX(L), PY(yl), pulse, 0, Math.PI * 2); ctx.fill();

// path labels
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("r1 = " + r1.toFixed(3) + " m", (PX(0) + PX(L)) / 2, (PY(sy1) + PY(yl)) / 2 - 10);
ctx.fillText("r2 = " + r2.toFixed(3) + " m", (PX(0) + PX(L)) / 2, (PY(sy2) + PY(yl)) / 2 + 12);
ctx.textAlign = "left";
ctx.fillText("speaker 1", PX(0) + 9, PY(sy1) - 16);
ctx.fillText("speaker 2", PX(0) + 9, PY(sy2) + 16);
ctx.textAlign = "right";
ctx.fillText("listener", PX(L) - 10, PY(yl) - 14);

// separation marker
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(PX(0) - 16, PY(sy1)); ctx.lineTo(PX(0) - 16, PY(sy2)); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.save();
ctx.translate(PX(0) - 22, cy);
ctx.rotate(-Math.PI / 2);
ctx.textAlign = "center";
ctx.fillText("d = " + d.toFixed(2) + " m", 0, 0);
ctx.restore();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("4.00 m", (PX(0) + PX(L)) / 2, H - 12);

var frac = Math.abs(n - Math.round(n));
var verdict;
if (frac < 0.06) { verdict = "LOUD (near a whole number of wavelengths)"; }
else if (Math.abs(frac - 0.5) < 0.06) { verdict = "QUIET (near a half-odd number)"; }
else { verdict = "in between"; }

out.note = "wavelength " + lam.toFixed(3) + " m, path difference " + dr.toFixed(3) +
  " m = " + n.toFixed(3) + " wavelengths  ->  " + verdict;

var ph = p.phase * Math.PI / 180;
var A = 1;
var R = 2 * A * Math.abs(Math.cos(ph / 2));

var cx = W * 0.30, cy = H * 0.62;
var len = Math.min(W * 0.20, H * 0.34);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

var arrow = function (x0, y0, x1, y1, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var an = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 9 * Math.cos(an - 0.4), y1 - 9 * Math.sin(an - 0.4));
  ctx.lineTo(x1 - 9 * Math.cos(an + 0.4), y1 - 9 * Math.sin(an + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
};

// phasor 1 along the x axis, phasor 2 tipped by the phase difference
var ax = cx + len, ay = cy;
var bx = ax + len * Math.cos(-ph), by = ay + len * Math.sin(-ph);

arrow(cx, cy, ax, ay, C.rule, 2);
arrow(ax, ay, bx, by, C.rule, 2);
arrow(cx, cy, bx, by, C.accent, 2.4);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("A", (cx + ax) / 2, ay + 14);
ctx.fillText("A", (ax + bx) / 2 + 12, (ay + by) / 2);
ctx.fillStyle = C.accent;
ctx.fillText("resultant", (cx + bx) / 2 - 6, (cy + by) / 2 - 14);

// the angle at the tip
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(ax, ay, 22, 0, -ph, ph > 0);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("phase difference " + p.phase.toFixed(0) + " deg", ax + 26, ay - 26);

// amplitude bar on the right
var bx0 = W * 0.80, top = H * 0.16, bot = H * 0.84;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(bx0 - 18, bot); ctx.lineTo(bx0 + 18, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx0 - 18, top); ctx.lineTo(bx0 + 18, top); ctx.stroke();
ctx.fillStyle = C.accent;
var hgt = (bot - top) * R / 2;
ctx.fillRect(bx0 - 12, bot - hgt, 24, hgt);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("2A", bx0, top - 10);
ctx.fillText("0", bx0, bot + 12);
ctx.fillText(R.toFixed(3) + " A", bx0, bot - hgt - 12);

out.note = "resultant amplitude = 2A|cos(" + (p.phase / 2).toFixed(1) +
  " deg)| = " + R.toFixed(3) + " A  -  zero at 180 deg, full 2A at 0 and 360 deg";
